package com.ksh321.songrecord.api.retention;
import org.junit.jupiter.api.Test;
class UploadFinalizationTests {
 @Test void immutableBytesAndAtomicFencedAccounting()throws Exception{var db=database();try(var c=db.getDataSource().getConnection()){new org.springframework.jdbc.datasource.init.ResourceDatabasePopulator(new org.springframework.core.io.ClassPathResource("job-schema.sql")).populate(c);UploadFinalizationDatabaseChecks.verify(db);}}
 @Test void mysqlDatetimeAndH2TimestampRepresentSameUtcExpiry(){var expected=java.time.Instant.parse("2026-10-09T12:00:00Z");org.assertj.core.api.Assertions.assertThat(com.ksh321.songrecord.api.uploads.UploadFinalization.instant(java.time.LocalDateTime.ofInstant(expected,java.time.ZoneOffset.UTC))).isEqualTo(expected);org.assertj.core.api.Assertions.assertThat(com.ksh321.songrecord.api.uploads.UploadFinalization.instant(java.sql.Timestamp.from(expected))).isEqualTo(expected);}
 static org.springframework.jdbc.core.JdbcTemplate database(){var db=UploadApprovalTests.database();db.execute("ALTER TABLE pin_slot ADD revision BIGINT DEFAULT 1");db.execute("ALTER TABLE pin_slot ADD updated_at TIMESTAMP");db.execute("ALTER TABLE user_sync_state ADD last_change_seq BIGINT DEFAULT 0");db.execute("ALTER TABLE user_sync_state ADD updated_at TIMESTAMP");db.execute("CREATE TABLE change_log(user_id BINARY(16),change_seq BIGINT,entity_type VARCHAR(64),entity_id BINARY(16),revision BIGINT,operation VARCHAR(16),payload VARCHAR(10000),created_at TIMESTAMP,expires_at TIMESTAMP,PRIMARY KEY(user_id,change_seq))");return db;}
}
